function HeroCarousel({ slides }) {
  const trackRef = useRef(null);
  const [active, setActive] = useState(0);
  const isJumping = useRef(false);

  useEffect(() => {
    const timer = setInterval(() => {
      goTo((active + 1) % slides.length);
    }, 4000);
    return () => clearInterval(timer);
  }, [active]);

  function goTo(index) {
    isJumping.current = true;
    setActive(index);
    const track = trackRef.current;
    if (track) {
      track.scrollTo({ left: index * track.clientWidth, behavior: "smooth" });
    }
    setTimeout(() => { isJumping.current = false; }, 500);
  }

  function onScroll() {
    if (isJumping.current) return;
    const track = trackRef.current;
    if (!track) return;
    const index = Math.round(track.scrollLeft / track.clientWidth);
    if (index !== active) setActive(index);
  }

  return (
    <div className="carousel">
      <div className="carousel-track" ref={trackRef} onScroll={onScroll}>
        {slides.map((slide, i) => (
          <div className="carousel-slide" key={i}>
            <div className="slide-logo-wrap">
              <img src={slide.img} alt={slide.label} className="slide-logo" />
            </div>
            <div className="slide-text">
              <span className="slide-label">— {slide.label}</span>
              <p>{slide.text}</p>
            </div>
          </div>
        ))}
      </div>
      <div className="carousel-dots">
        {slides.map((_, i) => (
          <button
            key={i}
            className={i === active ? "dot dot-active" : "dot"}
            onClick={() => goTo(i)}
            aria-label={`Go to slide ${i + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

